+/** Selects the highest-weight supported language, or the configured fallback. */
+export function requestLanguage(headers, fallback) {
+  const header = Object.entries(headers).find(([name]) => name.toLowerCase() === "accept-language")?.[1];
+  let language = fallback;
+  let bestQuality = 0;
+  for (const range of String(header ?? "").split(",")) {
+    const match = /^([a-z]+)(?:-[a-z0-9]{1,8})*(?:\s*;\s*q\s*=\s*(0(?:\.\d{0,3})?|1(?:\.0{0,3})?))?$/i.exec(range.trim());
+    if (!match) continue;
+    const candidate = match[1].toLowerCase();
+    const quality = Number(match[2] ?? 1);
+    if (LANGUAGES.includes(candidate) && quality > bestQuality) {
+      language = candidate;
+      bestQuality = quality;
+    }
+  }
+  return language;
+}
